# owner: platform
"""Contact sheet rows for substitute teachers."""

from rosterkit.errors import ProjectError


def _name_key(item):
    return item.display_name.casefold()


def _check(students):
    if not students:
        raise ProjectError("no students given")
    for item in students:
        if not item.email:
            name = item.display_name
            raise ProjectError(f"no email for {name}")


def _row(item, wide, secs):
    name = item.display_name.ljust(wide)
    sect = item.section.ljust(secs)
    return f"{name}  {sect}  {item.email}"


def contact_rows(students):
    _check(students)
    ordered = sorted(students, key=_name_key)
    wide = max(len(item.display_name) for item in ordered)
    secs = max(len(item.section) for item in ordered)
    return [_row(item, wide, secs) for item in ordered]

